pub fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    let m = arr.len();
    let n = arr[0].len();

    // If the matrix has zero columns (e.g., vec![vec![]]), the transpose has zero rows.
    if n == 0 {
        return Vec::new();
    }

    // Allocate n rows, each with capacity m.
    let mut out: Vec<Vec<i8>> = (0..n).map(|_| Vec::with_capacity(m)).collect();

    // Fill out[j][i] by pushing in row-major order over input.
    for i in 0..m {
        // Problem guarantees rectangular matrix; row length equals n.
        for j in 0..n {
            out[j].push(arr[i][j]);
        }
    }

    out
}